import React from 'react';
import { Input, Select, Button, Modal } from '@linm-soft-org/linm-web-common-components';
import { ValidationErrorBanner } from '../../../components/layout';
import {
  OrderLinesGrid,
  UnsavedChangesModal,
  useMaterialLinesSelection,
} from '../../../components/form';
import { CustomerSearchField } from '../../../components/search';
import {
  SalesVoucherFormFooter,
  SalesVoucherFormShell,
  SalesVoucherHeaderSection,
  VoucherFormBodySkeleton,
  VoucherFormFooterSkeleton,
  VoucherFormRow,
  VoucherFormToolbar,
} from '../../../components/voucher';
import { useTraHangBanFormPage } from '../../../hooks/useTraHangBanFormPage';
import df from '../../../styles/documentForm.module.css';

const TraHangBanFormPage: React.FC = () => {
  const vm = useTraHangBanFormPage();
  const { copyLine, lineRowProps, setSelectedLineIndex } = useMaterialLinesSelection(
    vm.lines,
    vm.setLines,
  );

  const addLine = () => {
    vm.addLine();
    setSelectedLineIndex(vm.lines.length);
  };

  const removeLine = (idx: number) => {
    vm.removeLine(idx);
    setSelectedLineIndex(Math.max(0, idx - 1));
  };

  const toolbar = (
    <div className={df.stickyTop}>
      <VoucherFormToolbar
        testIdPrefix={vm.TEST_ID}
        insetShell
        title={vm.isNew ? 'Tạo trả hàng' : `Trả hàng — ${vm.returnCode || '...'}`}
        formMode={vm.toolbarMode}
        viewModeHint={vm.viewModeHint}
        showApproveButton={false}
        canApprove={false}
        showPostButton={false}
        canPost={false}
        canCopy={vm.canCopy}
        canPrint={false}
        canHistory={false}
        copySourceVoucherCode={vm.copySourceVoucherCode}
        showEditButton={vm.showEditDelete}
        showDeleteButton={vm.showEditDelete}
        showNewButton={vm.canCreate}
        canEdit={vm.showEditDelete}
        canDelete={vm.showEditDelete}
        canSave={vm.canSave}
        saving={vm.saving}
        saveLabel={vm.isNew ? 'Tạo phiếu' : 'Lưu'}
        onBack={vm.handleBack}
        onApprove={() => {}}
        onPost={() => {}}
        onCopy={vm.handleCopy}
        onPrint={() => {}}
        onSearch={() => {}}
        onNew={vm.handleNew}
        onEdit={vm.handleEdit}
        onSave={vm.handleSave}
        onCancel={vm.handleCancel}
        onDelete={() => vm.setShowDeleteModal(true)}
        disabledReasons={vm.toolbarDisabledReasons}
      />
    </div>
  );

  if (vm.loading) {
    return (
      <SalesVoucherFormShell
        testIdPrefix={vm.TEST_ID}
        header={toolbar}
        footer={<VoucherFormFooterSkeleton testIdPrefix={vm.TEST_ID} />}
      >
        <VoucherFormBodySkeleton testIdPrefix={vm.TEST_ID} />
      </SalesVoucherFormShell>
    );
  }

  return (
    <>
      <SalesVoucherFormShell
        testIdPrefix={vm.TEST_ID}
        header={toolbar}
        footer={(
          <SalesVoucherFormFooter
            testIdPrefix={vm.TEST_ID}
            totals={[{ label: 'Tổng cộng:', amount: vm.total }]}
            processingLevel={vm.processingLevel}
            onProcessingLevelChange={vm.setProcessingLevel}
            processingLevelOptions={vm.processingLevelOptions}
            processingLevelDisabled={vm.processingLevelDisabled}
          />
        )}
      >
        <ValidationErrorBanner
          id={vm.validationBannerId}
          data-testid={vm.validationBannerId}
          errors={vm.validationErrors}
          closed={vm.bannerClosed}
          expanded={vm.bannerExpanded}
          onToggle={() => vm.setBannerExpanded(v => !v)}
          onClose={() => vm.setBannerClosed(true)}
        />

        <SalesVoucherHeaderSection
          title="Thông tin trả hàng"
          testIdPrefix={vm.TEST_ID}
          headerExpanded={vm.headerExpanded}
          setHeaderExpanded={vm.setHeaderExpanded}
          viewSectionClass={vm.fieldLock.viewSectionClass}
        >
          {({ fieldClass, compactHideClass, formRowStyles }) => (
            <VoucherFormRow styles={formRowStyles}>
              <div
                className={fieldClass(compactHideClass(true))}
                data-validation-target={vm.fieldErrors.returnDate ? 'true' : undefined}
              >
                <label className={df.label}>
                  Ngày trả
                  {vm.isNew ? ' *' : ''}
                </label>
                <Input
                  id={vm.tid('field-returnDate')}
                  type="date"
                  value={vm.returnDate}
                  error={vm.fieldErrors.returnDate}
                  onChange={e => {
                    const v = e.target.value;
                    vm.setReturnDate(v);
                    if (vm.isNew) vm.patchHeaderFieldError('returnDate', v);
                  }}
                  {...(vm.fieldLock.isReadOnly || !vm.isNew
                    ? { readOnly: true as const }
                    : {})}
                  data-testid={vm.tid('field-returnDate')}
                />
              </div>
              <div
                className={fieldClass(df.spanCol2, compactHideClass(true))}
                data-validation-target={vm.fieldErrors.customerId ? 'true' : undefined}
              >
                <label className={df.label}>
                  Khách hàng
                  {vm.isNew ? ' *' : ''}
                </label>
                <CustomerSearchField
                  customerId={vm.customerId}
                  customerCode={vm.customerCode}
                  customerName={vm.customerName}
                  onSelect={vm.customerHandlers.onSelect}
                  onClear={vm.customerHandlers.onClear}
                  disabled={!vm.canEditFields || !vm.isNew}
                  error={vm.fieldErrors.customerId}
                  testIdPrefix={`${vm.TEST_ID}-customer`}
                />
              </div>
              <div
                className={fieldClass(compactHideClass(false))}
                data-validation-target={vm.fieldErrors.warehouseId ? 'true' : undefined}
              >
                <label className={df.label}>Kho *</label>
                <Select
                  id={vm.tid('field-warehouseId')}
                  value={vm.warehouseId}
                  error={vm.fieldErrors.warehouseId}
                  onChange={e => {
                    const v = e.target.value;
                    vm.setWarehouseId(v);
                    vm.patchHeaderFieldError('warehouseId', v);
                  }}
                  options={vm.warehouseSelectOptions}
                  {...(vm.fieldLock.isReadOnly ? { disabled: true as const } : {})}
                  data-testid={vm.tid('field-warehouseId')}
                />
              </div>
              <div className={fieldClass(compactHideClass(false))}>
                <label className={df.label}>Lý do</label>
                <Input
                  value={vm.reason}
                  onChange={e => vm.setReason(e.target.value)}
                  {...vm.fieldLock.fieldLockProps}
                  data-testid={vm.tid('field-reason')}
                />
              </div>
            </VoucherFormRow>
          )}
        </SalesVoucherHeaderSection>
        <div
          id={vm.tid('lines-section')}
          className={[df.section, df.linesSection, vm.fieldLock.viewSectionClass]
            .filter(Boolean)
            .join(' ')}
          data-validation-target={vm.fieldErrors.linesGeneral ? 'true' : undefined}
        >
          <h2 className={df.sectionTitle}>Chi tiết hàng trả</h2>
          <OrderLinesGrid
            lines={vm.lines}
            canEdit={vm.canEditFields}
            lineErrors={vm.fieldErrors.lines}
            linesGeneralError={vm.fieldErrors.linesGeneral}
            testIdPrefix={vm.TEST_ID}
            onChange={vm.handleLinesChange}
            onAfterLineUpdate={vm.handleAfterLineUpdate}
            onAddLine={addLine}
            onCopyLine={copyLine}
            lineRowProps={lineRowProps}
            onRemoveLine={removeLine}
          />
        </div>
      </SalesVoucherFormShell>

      <UnsavedChangesModal
        isOpen={vm.showUnsavedModal}
        onStay={vm.cancelLeave}
        onLeave={vm.confirmLeave}
        data-testid={`${vm.TEST_ID}-unsaved-modal`}
      />

      <Modal
        isOpen={vm.showDeleteModal}
        onClose={() => vm.setShowDeleteModal(false)}
        title="Xác nhận xóa phiếu trả hàng"
      >
        <p data-testid={`${vm.TEST_ID}-delete-confirm-message`}>
          Xóa phiếu trả hàng <strong>{vm.returnCode || 'này'}</strong>? Thao tác không thể hoàn tác.
        </p>
        <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 16 }}>
          <Button
            variant="secondary"
            onClick={() => vm.setShowDeleteModal(false)}
            data-testid={`${vm.TEST_ID}-delete-cancel`}
          >
            Hủy
          </Button>
          <Button
            variant="danger"
            onClick={vm.handleDelete}
            loading={vm.deleting}
            data-testid={`${vm.TEST_ID}-delete-confirm`}
          >
            Xóa
          </Button>
        </div>
      </Modal>
    </>
  );
};

export default TraHangBanFormPage;
