import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useLocation, useParams } from 'react-router-dom';
import { dispatchAppToast } from '@linm-soft-org/linm-web-common-components';
import {
  FormMode,
  effectiveFormMode,
  initialFormMode,
  isEditingMode,
  isViewMode,
  useFormFieldLock,
  shouldStartFormInEditMode,
  withFormEditModeSearch,
  withoutFormEditModeSearch,
} from '../components/form';
import type { FormNavigateEditIntent } from '../components/form';
import {
  VOUCHER_COPY_STATE_KEY,
  VOUCHER_COPY_SOURCE_CODE_KEY,
} from '../components/voucher/voucherFormConstants';
import {
  buildVoucherToolbarDisabledReasons,
  resolveVoucherViewModeHint,
} from '../utils/invoiceProcessingLevelDisplay';
import { useInAppNavigate } from '../router/useInAppNavigate';
import { useAppDispatch } from '../store/hooks';
import { bhService } from '../services/bh/bhService';
import type { OrderLineDto } from '../services/bh/models';
import type { CustomerDto } from '../services/master/models';
import { getApiErrorMessage } from '../utils/getApiErrorMessage';
import { customerFieldHandlers, loadCustomerDisplay } from '../utils/customerField';
import {
  collectSalesReturnBannerMessages,
  insertSalesReturnLineFieldErrors,
  shiftSalesReturnLineFieldErrors,
  scrollToFirstSalesReturnFieldError,
  validateSalesReturnFields,
  validateSalesReturnHeaderField,
  validateSalesReturnLineField,
  type SalesReturnFieldErrors,
  type SalesReturnLineFieldKey,
} from '../utils/salesReturnFieldValidation';
import { emptyOrderLine, normalizeOrderLines, orderLinesTotal } from '../utils/orderLines';
import { canEditSalesReturnFromListRow } from '../utils/salesReturnListRowActions';
import { toDateOnlyInputValue } from '../utils/dateUtils';
import { useSalesFormProcessingLevel } from './useSalesFormProcessingLevel';
import { useUnsavedChangesGuard } from './useUnsavedChangesGuard';
import { useVoucherInitData } from './useVoucherInitData';
import { useVoucherListActions } from './useVoucherListActions';
import df from '../styles/documentForm.module.css';

const TEST_ID = 'tra-hang';
const LIST_PATH = '/bh/tra-hang';
const CREATE_PATH = '/bh/tra-hang/them';
const INIT_CREATE = 'create-sales-return';
const INIT_EDIT = 'edit-sales-return';

type FormSnapshot = {
  returnDate: string;
  customerId: string;
  warehouseId: string;
  reason: string;
  lines: OrderLineDto[];
};

function buildSnapshot(state: FormSnapshot): string {
  return JSON.stringify(state);
}

function isReturnStatusLocked(status: string): boolean {
  return status !== 'Draft';
}

function nextLinesHasValidLine(
  lines: OrderLineDto[],
  idx: number,
  updated: OrderLineDto,
): boolean {
  const merged = lines.map((l, i) => (i === idx ? updated : l));
  return merged.some(l => l.materialCode?.trim() && Number(l.quantity) > 0);
}

export function useTraHangBanFormPage() {
  const { id } = useParams<{ id: string }>();
  const isNew = !id;
  const navigate = useInAppNavigate();
  const location = useLocation();
  const dispatch = useAppDispatch();
  const tid = (suffix: string) => `${TEST_ID}-${suffix}`;
  const validationBannerId = tid('validation-banner');
  const { canCreate, canUpdate } = useVoucherListActions(INIT_CREATE);
  const initFormName = isNew ? INIT_CREATE : INIT_EDIT;
  const { warehouseOptions } = useVoucherInitData(initFormName);
  const {
    processingLevel,
    setProcessingLevel,
    processingLevelOptions,
  } = useSalesFormProcessingLevel(initFormName);

  const warehouseSelectOptions = useMemo(
    () => [{ value: '', label: '— Chọn kho —' }, ...warehouseOptions],
    [warehouseOptions],
  );

  const [formMode, setFormMode] = useState<FormMode>(() => initialFormMode(isNew));
  const toolbarMode = effectiveFormMode(isNew, formMode);

  const [status, setStatus] = useState('Draft');
  const [returnCode, setReturnCode] = useState('');
  const [returnDate, setReturnDate] = useState(() => toDateOnlyInputValue(new Date().toISOString()));
  const [customerId, setCustomerId] = useState('');
  const [customerCode, setCustomerCode] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [warehouseId, setWarehouseId] = useState('');
  const [reason, setReason] = useState('');
  const [lines, setLines] = useState<OrderLineDto[]>([emptyOrderLine()]);
  const [loading, setLoading] = useState(!isNew);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [headerExpanded, setHeaderExpanded] = useState(true);
  const [savedSnapshot, setSavedSnapshot] = useState('');
  const [fieldErrors, setFieldErrors] = useState<SalesReturnFieldErrors>({});
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [bannerClosed, setBannerClosed] = useState(false);
  const [bannerExpanded, setBannerExpanded] = useState(true);
  const [copySourceVoucherCode, setCopySourceVoucherCode] = useState<string | null>(null);
  const savedStateRef = useRef<FormSnapshot | null>(null);
  const copyAppliedRef = useRef(false);

  const applySnapshot = useCallback((snap: FormSnapshot) => {
    savedStateRef.current = snap;
    setSavedSnapshot(buildSnapshot(snap));
  }, []);

  const isStatusLocked = !isNew && isReturnStatusLocked(status);
  const showEditDelete = !isNew && canUpdate && !isStatusLocked;
  const fieldLock = useFormFieldLock({
    formMode: toolbarMode,
    isStatusLocked,
    styles: {
      viewReadOnlySection: df.viewReadOnlySection,
      searchViewOnly: df.searchViewOnly,
      embeddedSearch: df.lineMaterialSearch,
    },
  });

  const canEditFields = isEditingMode(toolbarMode) && !isStatusLocked;
  const currentSnap = buildSnapshot({ returnDate, customerId, warehouseId, reason, lines });
  const isDirty =
    isEditingMode(toolbarMode) && Boolean(savedSnapshot) && currentSnap !== savedSnapshot;

  const { guardedAction, showUnsavedModal, confirmLeave, cancelLeave } =
    useUnsavedChangesGuard(isDirty, isEditingMode(toolbarMode));

  const viewModeHint = resolveVoucherViewModeHint({
    formMode: toolbarMode,
    isNew,
    status,
    processingLevel,
    canEditWhenView: showEditDelete,
  });

  const toolbarDisabledReasons = buildVoucherToolbarDisabledReasons({
    isNew,
    status,
    isStatusLocked,
    draftOnlyMessage: 'Chỉ thao tác trên phiếu trả hàng ở trạng thái Nháp',
  });

  useEffect(() => {
    setValidationErrors(collectSalesReturnBannerMessages(fieldErrors));
    if (Object.keys(fieldErrors).length === 0) {
      setBannerClosed(false);
    }
  }, [fieldErrors]);

  // Copy hydrate on create route
  useEffect(() => {
    if (!isNew || copyAppliedRef.current) return;
    const copyState = (location.state as Record<string, unknown>)?.[VOUCHER_COPY_STATE_KEY];
    const sourceCode = (location.state as Record<string, unknown>)?.[VOUCHER_COPY_SOURCE_CODE_KEY] as string | undefined;
    if (!copyState || !sourceCode) return;
    copyAppliedRef.current = true;
    const snap = copyState as FormSnapshot;
    const mappedLines = snap.lines?.length
      ? snap.lines.map(l => ({ ...l, id: undefined }))
      : [emptyOrderLine()];
    setReturnDate(snap.returnDate);
    setCustomerId(snap.customerId);
    setWarehouseId(snap.warehouseId);
    setReason(snap.reason ?? '');
    setLines(mappedLines);
    setCopySourceVoucherCode(sourceCode);
    loadCustomerDisplay(snap.customerId, undefined)
      .then(display => {
        setCustomerCode(display.code);
        setCustomerName(display.name);
      })
      .catch(() => {});
    applySnapshot({
      returnDate: snap.returnDate,
      customerId: snap.customerId,
      warehouseId: snap.warehouseId,
      reason: snap.reason ?? '',
      lines: mappedLines,
    });
  }, [isNew, location.state, applySnapshot]);

  // Clean create — baseline after first paint
  useEffect(() => {
    if (!isNew || savedSnapshot || copyAppliedRef.current) return;
    applySnapshot({
      returnDate,
      customerId,
      warehouseId,
      reason,
      lines,
    });
  }, [isNew, savedSnapshot, returnDate, customerId, warehouseId, reason, lines, applySnapshot]);

  // List → Edit intent
  const editIntentAppliedForIdRef = useRef<string | null>(null);
  useEffect(() => {
    if (isNew) {
      editIntentAppliedForIdRef.current = null;
      return;
    }
    const hasEditIntent = shouldStartFormInEditMode(
      location.search,
      location.state as FormNavigateEditIntent | null,
    );
    if (!hasEditIntent) {
      if (editIntentAppliedForIdRef.current === id) {
        editIntentAppliedForIdRef.current = null;
      }
      return;
    }
    if (editIntentAppliedForIdRef.current === id) return;
    editIntentAppliedForIdRef.current = id ?? null;
    if (showEditDelete || canEditSalesReturnFromListRow(status, canUpdate)) {
      setFormMode(FormMode.Edit);
    }
  }, [isNew, id, location.search, location.state, showEditDelete, status, canUpdate]);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    setLoading(true);
    const t = setTimeout(() => {
      bhService.getSalesReturn(id)
        .then(async r => {
          if (cancelled) return;
          const dateVal = toDateOnlyInputValue(r.returnDate);
          const mappedLines = r.lines?.length ? r.lines : [emptyOrderLine()];
          setReturnCode(r.code);
          setStatus(r.status ?? 'Draft');
          setReturnDate(dateVal);
          setCustomerId(r.customerId);
          setWarehouseId(r.warehouseId);
          setReason(r.reason ?? '');
          setLines(mappedLines);
          const display = await loadCustomerDisplay(r.customerId, r.customerName);
          if (!cancelled) {
            setCustomerCode(display.code);
            setCustomerName(display.name);
            applySnapshot({
              returnDate: dateVal,
              customerId: r.customerId,
              warehouseId: r.warehouseId,
              reason: r.reason ?? '',
              lines: mappedLines,
            });
          }
        })
        .catch(err => {
          if (!cancelled) {
            dispatchAppToast(dispatch, {
              message: getApiErrorMessage(err, 'Lỗi tải phiếu trả hàng'),
              type: 'error',
            });
          }
        })
        .finally(() => {
          if (!cancelled) setLoading(false);
        });
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(t);
    };
  }, [id, dispatch, applySnapshot]);

  const patchHeaderFieldError = useCallback((
    key: 'returnDate' | 'customerId' | 'warehouseId',
    value: string,
  ) => {
    setFieldErrors(prev => {
      const msg = validateSalesReturnHeaderField(key, value);
      const next = { ...prev, [key]: msg };
      if (!msg) delete next[key];
      return next;
    });
    setBannerClosed(false);
  }, []);

  const patchLineFieldError = useCallback((
    lineIndex: number,
    key: SalesReturnLineFieldKey,
    line: OrderLineDto,
  ) => {
    setFieldErrors(prev => {
      const msg = validateSalesReturnLineField(lineIndex, key, line);
      const nextLines = { ...prev.lines };
      const row = { ...(nextLines[lineIndex] ?? {}) };
      if (msg) row[key] = msg;
      else delete row[key];
      if (Object.keys(row).length > 0) nextLines[lineIndex] = row;
      else delete nextLines[lineIndex];
      const next: SalesReturnFieldErrors = {
        ...prev,
        lines: Object.keys(nextLines).length > 0 ? nextLines : undefined,
      };
      if (next.linesGeneral && line.materialCode?.trim() && Number(line.quantity) > 0) {
        delete next.linesGeneral;
      }
      return next;
    });
    setBannerClosed(false);
  }, []);

  const baseCustomerHandlers = useMemo(
    () => customerFieldHandlers(setCustomerId, setCustomerCode, setCustomerName),
    [],
  );

  const customerHandlers = useMemo(
    () => ({
      onSelect: (customer: CustomerDto) => {
        baseCustomerHandlers.onSelect(customer);
        patchHeaderFieldError('customerId', customer.customerId);
      },
      onClear: () => {
        baseCustomerHandlers.onClear();
        patchHeaderFieldError('customerId', '');
      },
    }),
    [baseCustomerHandlers, patchHeaderFieldError],
  );

  const handleLinesChange = useCallback((nextLines: OrderLineDto[]) => {
    setLines(nextLines);
  }, []);

  const handleAfterLineUpdate = useCallback((
    idx: number,
    line: OrderLineDto,
    key: SalesReturnLineFieldKey,
  ) => {
    patchLineFieldError(idx, key, line);
    setFieldErrors(prev => {
      if (!prev.linesGeneral) return prev;
      const hasValid = nextLinesHasValidLine(lines, idx, line);
      if (!hasValid) return prev;
      const next = { ...prev };
      delete next.linesGeneral;
      return next;
    });
  }, [patchLineFieldError, lines]);

  const addLine = useCallback(() => {
    if (!canEditFields) return;
    const insertAt = lines.length;
    setLines(prev => [...prev, emptyOrderLine()]);
    setFieldErrors(prev => ({
      ...prev,
      lines: insertSalesReturnLineFieldErrors(prev.lines, insertAt),
    }));
  }, [canEditFields, lines.length]);

  const removeLine = useCallback((idx: number) => {
    if (!canEditFields) return;
    setLines(prev => {
      const next = prev.filter((_, i) => i !== idx);
      return next.length ? next : [emptyOrderLine()];
    });
    setFieldErrors(prev => ({
      ...prev,
      lines: shiftSalesReturnLineFieldErrors(prev.lines, idx),
    }));
  }, [canEditFields]);

  const restoreSaved = useCallback(() => {
    const snap = savedStateRef.current;
    if (!snap) return;
    setReturnDate(snap.returnDate);
    setCustomerId(snap.customerId);
    setWarehouseId(snap.warehouseId);
    setReason(snap.reason);
    setLines(snap.lines.map(l => ({ ...l })));
    setSavedSnapshot(buildSnapshot(snap));
    loadCustomerDisplay(snap.customerId, undefined)
      .then(display => {
        setCustomerCode(display.code);
        setCustomerName(display.name);
      })
      .catch(() => {});
  }, []);

  const handleBack = useCallback(() => {
    guardedAction(() => navigate(LIST_PATH));
  }, [guardedAction, navigate]);

  const handleEdit = useCallback(() => {
    if (!showEditDelete) return;
    setFormMode(FormMode.Edit);
    if (!isNew) {
      const nextSearch = withFormEditModeSearch(location.search);
      if (nextSearch !== location.search) {
        navigate(
          { pathname: location.pathname, search: nextSearch },
          { replace: true, state: location.state },
        );
      }
    }
  }, [showEditDelete, isNew, location.pathname, location.search, location.state, navigate]);

  const handleCancel = useCallback(() => {
    if (isNew) {
      guardedAction(() => navigate(LIST_PATH));
      return;
    }
    restoreSaved();
    setFormMode(FormMode.View);
    setHeaderExpanded(true);
    setFieldErrors({});
    const nextSearch = withoutFormEditModeSearch(location.search);
    if (nextSearch !== location.search) {
      navigate(
        { pathname: location.pathname, search: nextSearch },
        { replace: true, state: location.state },
      );
    }
  }, [isNew, guardedAction, navigate, restoreSaved, location.pathname, location.search, location.state]);

  const handleCopy = useCallback(() => {
    if (isNew) return;
    guardedAction(() => {
      const snap: FormSnapshot = {
        returnDate,
        customerId,
        warehouseId,
        reason,
        lines: lines.map(l => ({ ...l, id: undefined })),
      };
      navigate(CREATE_PATH, {
        state: {
          [VOUCHER_COPY_STATE_KEY]: snap,
          [VOUCHER_COPY_SOURCE_CODE_KEY]: returnCode,
        },
      });
    });
  }, [isNew, guardedAction, navigate, returnDate, customerId, warehouseId, reason, lines, returnCode]);

  const handleSave = useCallback(async () => {
    const validation = validateSalesReturnFields({
      isNew,
      returnDate,
      customerId,
      warehouseId,
      lines,
    });
    if (validation.bannerMessages.length > 0) {
      setFieldErrors(validation.fieldErrors);
      setBannerClosed(false);
      setBannerExpanded(true);
      scrollToFirstSalesReturnFieldError(validation.fieldErrors, tid, validationBannerId);
      return;
    }
    setFieldErrors({});
    const normalized = normalizeOrderLines(lines);
    setSaving(true);
    try {
      if (!isNew && id) {
        const updated = await bhService.updateSalesReturn(id, {
          warehouseId,
          reason,
          lines: normalized,
        });
        dispatchAppToast(dispatch, { message: 'Cập nhật trả hàng thành công', type: 'success' });
        const dateVal = toDateOnlyInputValue(updated.returnDate);
        const mappedLines = updated.lines?.length ? updated.lines : [emptyOrderLine()];
        setReturnCode(updated.code);
        setStatus(updated.status ?? 'Draft');
        setWarehouseId(updated.warehouseId);
        setReason(updated.reason ?? '');
        setLines(mappedLines);
        applySnapshot({
          returnDate: dateVal,
          customerId: updated.customerId,
          warehouseId: updated.warehouseId,
          reason: updated.reason ?? '',
          lines: mappedLines,
        });
        setFormMode(FormMode.View);
        setHeaderExpanded(true);
        const nextSearch = withoutFormEditModeSearch(location.search);
        if (nextSearch !== location.search) {
          navigate(
            { pathname: location.pathname, search: nextSearch },
            { replace: true, state: location.state },
          );
        }
      } else {
        await bhService.createSalesReturn({
          returnDate,
          customerId,
          warehouseId,
          reason,
          lines: normalized,
        });
        dispatchAppToast(dispatch, { message: 'Tạo trả hàng thành công', type: 'success' });
        navigate(LIST_PATH, { replace: true });
      }
    } catch (err: unknown) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Lưu thất bại'),
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  }, [
    isNew, id, returnDate, customerId, warehouseId, reason, lines, dispatch, applySnapshot,
    location.pathname, location.search, location.state, navigate, tid, validationBannerId,
  ]);

  const handleDelete = useCallback(async () => {
    if (!id || !showEditDelete) return;
    setDeleting(true);
    try {
      await bhService.deleteSalesReturn(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu trả hàng', type: 'success' });
      setShowDeleteModal(false);
      navigate(LIST_PATH);
    } catch (err: unknown) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Xóa thất bại'),
        type: 'error',
      });
    } finally {
      setDeleting(false);
    }
  }, [id, showEditDelete, dispatch, navigate]);

  const total = orderLinesTotal(lines);

  return {
    TEST_ID,
    tid,
    validationBannerId,
    isNew,
    id,
    toolbarMode,
    fieldLock,
    canEditFields,
    isViewMode: isViewMode(toolbarMode),
    loading,
    saving,
    deleting,
    showDeleteModal,
    setShowDeleteModal,
    returnCode,
    status,
    returnDate,
    setReturnDate,
    customerId,
    customerCode,
    customerName,
    customerHandlers,
    warehouseId,
    setWarehouseId,
    warehouseSelectOptions,
    reason,
    setReason,
    lines,
    setLines,
    addLine,
    removeLine,
    handleLinesChange,
    handleAfterLineUpdate,
    patchHeaderFieldError,
    headerExpanded,
    setHeaderExpanded,
    fieldErrors,
    validationErrors,
    bannerClosed,
    setBannerClosed,
    bannerExpanded,
    setBannerExpanded,
    processingLevel,
    setProcessingLevel,
    processingLevelOptions,
    processingLevelDisabled: !canEditFields,
    total,
    canCreate,
    showEditDelete,
    canCopy: !isNew,
    canSave: isNew ? canCreate : canUpdate,
    copySourceVoucherCode,
    viewModeHint,
    toolbarDisabledReasons,
    handleBack,
    handleEdit,
    handleCancel,
    handleSave,
    handleCopy,
    handleDelete,
    handleNew: () => guardedAction(() => navigate(CREATE_PATH)),
    showUnsavedModal,
    confirmLeave,
    cancelLeave,
  };
}
